{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "catalog",
      "host": "catalog.internal",
      "port": 7640,
      "weight": 6,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 9337,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "payments",
      "host": "payments.internal",
      "port": 7377,
      "weight": 7,
      "health_check": "/healthz"
    },
    {
      "name": "reviews",
      "host": "reviews.internal",
      "port": 9643,
      "weight": 4,
      "health_check": "/healthz"
    },
    {
      "name": "media",
      "host": "media.internal",
      "port": 9037,
      "weight": 6,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/payments/audit",
      "upstream": "payments",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/media/settings",
      "upstream": "media",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 0
    },
    {
      "path": "/api/v1/carts/tokens",
      "upstream": "carts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 5000,
      "retries": 2
    },
    {
      "path": "/api/v1/catalog/summary",
      "upstream": "catalog",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 0
    },
    {
      "path": "/api/v1/payments/summary",
      "upstream": "payments",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/payments/quotes",
      "upstream": "payments",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 4500,
      "retries": 1
    },
    {
      "path": "/api/v1/catalog/tokens",
      "upstream": "catalog",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2500,
      "retries": 1
    },
    {
      "path": "/api/v1/carts/labels",
      "upstream": "carts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2000,
      "retries": 1
    },
    {
      "path": "/api/v1/media/summary",
      "upstream": "media",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 3000,
      "retries": 2
    },
    {
      "path": "/api/v1/media/labels",
      "upstream": "media",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 1
    }
  ]
}

